const { initialize, getConfigurationByKey, byCodeAndLevel } = require('@adobe/aio-commerce-lib-config')

const CONFIG_KEY = 'COMMERCE_CORE_GRAPHQL_URL'
const GLOBAL_SCOPE = byCodeAndLevel('global', 'global')

let schemaInitPromise = null

function loadBusinessConfigSchema () {
  // Generated by `npx aio-commerce-lib-app generate all` when businessConfig is defined.
  return require('../../../src/commerce-configuration-1/.generated/configuration-schema.json')
}

async function ensureBusinessConfigSchema () {
  if (!schemaInitPromise) {
    schemaInitPromise = Promise.resolve(
      initialize({ schema: loadBusinessConfigSchema() })
    )
  }
  await schemaInitPromise
}

/**
 * Resolves COMMERCE_CORE_GRAPHQL_URL from App Management business configuration (global scope),
 * with optional fallback to the action input / workspace env for local development.
 */
async function resolveCommerceCoreGraphqlUrl (params) {
  const fromEnv = String(params.COMMERCE_CORE_GRAPHQL_URL || '').trim()
  if (fromEnv) {
    return fromEnv
  }

  await ensureBusinessConfigSchema()
  const encryptionKey = String(params.AIO_COMMERCE_CONFIG_ENCRYPTION_KEY || '').trim() || undefined
  const result = await getConfigurationByKey(CONFIG_KEY, GLOBAL_SCOPE, { encryptionKey })
  const value = result?.config?.value
  if (typeof value === 'string' && value.trim()) {
    return value.trim()
  }
  return undefined
}

/** Returns a shallow copy of params with COMMERCE_CORE_GRAPHQL_URL set when available. */
async function withCommerceCoreGraphqlUrl (params) {
  const url = await resolveCommerceCoreGraphqlUrl(params)
  if (!url) {
    return params
  }
  return { ...params, COMMERCE_CORE_GRAPHQL_URL: url }
}

module.exports = {
  withCommerceCoreGraphqlUrl,
  resolveCommerceCoreGraphqlUrl
}
